{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "students’ early warning signs, such as bullying, threats of violence, substance abuse, mental health concerns, self-harm, or suicidal thoughts",
      "rationale": "Conveys several nonexclusive examples, but omits the broader safety, health, or behavioral definition and the express coverage of victims, recipients of threats, harassment, intimidation, and cyber-bullying."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "The bill would require each local education agency (LEA) and public charter school to use a computer-based system for reporting students’ early warning signs, such as bullying, threats of violence, substance abuse, mental health concerns, self-harm, or suicidal thoughts. Teachers and school staff would have to enter observed signs and receive training to identify them and use the system.",
      "rationale": "Conveys the system requirement for each LEA and public charter school and mandatory data entry by teachers and school staff."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "Teachers and school staff would have to enter observed signs and receive training to identify them and use the system.",
      "rationale": "Conveys required training for teachers and school staff in both identifying signs and using the reporting system."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "The system would have to align with specified school discipline and safety requirements",
      "rationale": "Conveys mandatory alignment generally, but does not identify § 49-6-4503, the School Discipline Act, or the schools’ safety plans adopted under SAVE."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "The system would have to align with specified school discipline and safety requirements, keep the entered data",
      "rationale": "In the context of the preceding staff data-entry requirement, keeping the entered data conveys the required receiving and maintaining database function."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "immediately alert the LEA’s or school’s threat assessment team when a sign is entered",
      "rationale": "Conveys the immediate notification trigger and the responsible threat assessment team recipients."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "Team personnel would review the alert and any earlier alerts for that student and decide whether further action is needed.",
      "rationale": "Conveys review of both current and prior notifications and the determination whether further action is necessary."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "Each LEA and public charter school would also have to report annually to the Department of Education on data collected during the prior school year and any interventions provided.",
      "rationale": "Includes the reporting actors, recipient, annual frequency, reporting period, and interventions."
    },
    {
      "proposition_id": "P9",
      "status": "partial",
      "summary_quote": "Reports would have to comply with specified student privacy and other laws.",
      "rationale": "Conveys a privacy compliance requirement but does not identify FERPA, § 10-7-504, or the Data Accessibility, Transparency, and Accountability Act."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "If the education commissioner found an LEA or public charter school out of compliance, the commissioner could withhold a determined amount of state funds until compliance.",
      "rationale": "Conveys the commissioner's discretionary withholding authority, noncompliance condition, affected entities, and duration; the amount determination is conveyed in context."
    },
    {
      "proposition_id": "P11",
      "status": "full",
      "summary_quote": "The bill would also amend existing provisions on threat assessment teams by adding public charter schools and their governing bodies and directors to the text",
      "rationale": "Conveys the extension to charter schools, governing bodies, and directors. The bill itself identifies § 49-6-2701 as the threat assessment team provision, so the target is identifiable without its number."
    },
    {
      "proposition_id": "P12",
      "status": "partial",
      "summary_quote": "The bill would also amend existing provisions on threat assessment teams by adding public charter schools and their governing bodies and directors to the text",
      "rationale": "Broadly conveys adding public charter schools to existing provisions, but does not identify the separate amendment to § 49-6-2702(b), whose target cannot otherwise be identified from the supplied bill."
    },
    {
      "proposition_id": "P13",
      "status": "full",
      "summary_quote": "The bill would take effect July 1, 2025.",
      "rationale": "States the exact effective date."
    }
  ]
}
